INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('CIA-V2-0014', '3', '3. El profesional de la medicina especialista en medicina crítica y cuidado intensivo cuenta con constancia de asistencia en acciones de formación continua para la gestión operativa de la donación, de conformidad con las normas que regulen la materia, o aquellas que las adicionen, modifiquen o sustituyan.', '', 'a77e9f96-0acb-480e-9bcb-23215e23693f'::uuid, '5d9b6120-d816-4760-b63a-2a27ffadda6b'::uuid, false, 14, 'active');
