INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('CIA-V2-0018', '6', '6. Profesional de la medicina especialista en medicina crítica y cuidado intensivo, cuando esté en disponibilidad y no se requiera su permanencia, puede hacer uso de la categoría telexperticia sincrónica, entre profesionales de la salud de acuerdo con lo definido por el prestador de servicios de salud en el estándar de procesos prioritarios.', '', 'a77e9f96-0acb-480e-9bcb-23215e23693f'::uuid, '5d9b6120-d816-4760-b63a-2a27ffadda6b'::uuid, false, 18, 'active');
