INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('CINN-V2-0016', '5', '5. El profesional de salud puede hacer uso de la categoría telexperticia sincrónica entre profesionales de la salud de acuerdo con lo definido por el prestador de servicios de salud en el estándar de procesos prioritarios.', '', '70804a4b-e8c7-4f70-89b2-37a29097ba1d'::uuid, 'b60d482c-10a0-413e-a2b7-9e889ee7c74e'::uuid, false, 16, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('CINN-V2-0017', '6', '6. Profesional de la medicina especialista en neonatología, cuando esté en disponibilidad y no se requiera su permanencia, puede hacer uso de la categoría telexperticia sincrónica, entre profesionales de la salud de acuerdo con lo definido por el prestador de servicios de salud en el estándar de procesos prioritarios.', '', '70804a4b-e8c7-4f70-89b2-37a29097ba1d'::uuid, 'b60d482c-10a0-413e-a2b7-9e889ee7c74e'::uuid, false, 17, 'active');
