INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HGP-V2-0163', '40.3', '40.3. Garantía de las condiciones de almacenamiento para las unidades de sangre de cordón umbilical la cuales deben estar a temperatura menor o igual a menos -120 grados centígrados y sangre periférica o médula ósea a menos -84 grados centígrados, en el caso de infusión posterior a 48 horas de recolectado. Si el producto va a ser infundido durante las 48 horas de recolectado, se almacena entre 2 y 8 grados centígrados.', '', '8624fcfe-5223-45d3-8635-448809025d20'::uuid, '04966178-fc65-4e5d-bb46-9f32b828128b'::uuid, false, 163, 'active');
