INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0019', '5', '5. Cumple con los criterios que le sean aplicables de todos los servicios, y adicionalmente cuenta con profesional de la salud, de acuerdo con lo definido por el prestador de servicios de salud en el estándar de procesos prioritarios.', '', '8bed88b6-175c-48cb-9e94-588a2bcceeea'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 19, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0020', '6', '6. Profesional de la medicina cuando esté en disponibilidad y no se requiera su permanencia, puede hacer uso de la categoría telexperticia sincrónica o asincrónica, entre profesionales de la salud de acuerdo con lo definido por el prestador de servicios de salud en el estándar de procesos prioritarios.', '', '8bed88b6-175c-48cb-9e94-588a2bcceeea'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 20, 'active');
