INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0085', '32.4', '32.4. Habitación individual o múltiple para pacientes adultos, pediátricos o lactantes, según oferta, que cuenta con:', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 85, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0086', '32.4.1', '32.4.1. Lavamanos, sanitario, ducha, área de guardarropa y sistema de llamado por cama o cuna.', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 86, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0087', '32.4.2', '32.4.2. La habitación individual para pacientes adultos, pediátricos o lactantes debe tener un área mínima de 16 m2.', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 87, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0088', '32.4.3', '32.4.3. La habitación múltiple para pacientes adultos debe tener una capacidad máxima de 4 camas, con área libre mínima de 7 m2 por cama, separadas con barrera física fija o móvil.', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 88, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0089', '32.4.4', '32.4.4. La habitación múltiple para pacientes pediátricos debe tener una capacidad máxima de 6 camas, con área libre mínima de 6 m2 por cama, separadas con barrera física fija o móvil.', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 89, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0090', '32.4.5', '32.4.5. La habitación múltiple para lactantes debe tener un área libre mínima de 4 m2 por cuna, con área para bañar y vestir a los lactantes y unidad sanitaria para acompañante. La capacidad máxima de cunas será definida por el prestador según su capacidad instalada.', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 90, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0091', '32.4.6', '32.4.6. Las habitaciones para pacientes adultos deben estar separadas de las habitaciones para pacientes pediátricos.', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 91, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0092', '32.4.7', '32.4.7. Las habitaciones para pacientes pediátricos cuentan con sistema de seguridad en las ventanas, mecanismos de protección en las instalaciones eléctricas y los aparatos sanitarios y muebles, deben tener la altura adecuada que permita al paciente su fácil utilización.', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 92, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0093', '32.4.8', '32.4.8. Las puertas de acceso a las habitaciones deben permitir el paso y giro de camillas y sillas de ruedas.', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 93, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('HPP-V2-0094', '32.4.9', '32.4.9. El ambiente donde esté ubicado el sanitario y la ducha debe permitir el fácil desplazamiento del paciente y contar con sistema de llamado de enfermería audible y visible.', '', '9c9263b2-133a-4563-af60-a76894c39ec9'::uuid, '94347eba-b5bb-4bad-8312-868b4bfacfa2'::uuid, false, 94, 'active');
