INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('IDX-V2-0007', '', 'Médico especializado en radiología e imágenes diagnósticas o aquellos médicos especialistas quienes en su pensum o formación académica hayan adquirido los conocimientos del manejo e interpretación del espectro electromagnético, del ultrasonido especialmente, así como de las radiaciones ionizantes para establecer el diagnóstico y/o el tratamiento de las enfermedades inherentes a sus especialidades, para lo cual deberán acreditar el respectivo certificado. La interpretación de las radiografías e imágenes diagnósticas y la supervisión del técnico profesional o tecnólogo en imágenes diagnósticas es realizada por dichos profesionales.', '', '74a03c07-05de-4949-a12f-d825e765103c'::uuid, '4ae1a9f0-0b78-4122-a35e-04ba44fbc3b6'::uuid, false, 7, 'active');
