INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('LAB-V2-0005', '1.1.2', '1.1.2. Talento humano profesional que cuenta con constancia de asistencia en las acciones de formación continua en las actividades relacionadas con el laboratorio clínico, cuando se requiera.', '', '21f3ec1f-4bc6-46ec-9e30-945d70983f9d'::uuid, '3b803ade-85a8-4039-8c6b-18abc4f46fb6'::uuid, false, 5, 'active');
