INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('LAB-V2-0007', '1.1.4', '1.1.4. Talento humano que cuenta con constancia de asistencia en las acciones de formación continua para el desarrollo de los programas para diagnóstico y control de enfermedades transmitidas por vectores, cuando se requiera.', '', '21f3ec1f-4bc6-46ec-9e30-945d70983f9d'::uuid, '3b803ade-85a8-4039-8c6b-18abc4f46fb6'::uuid, false, 7, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('LAB-V2-0008', '2', '2. Disponibilidad de bacteriólogo en zonas dispersas con permanencia de acuerdo con lo definido por el prestador de servicios de salud en el estándar de procesos prioritarios.', '', '21f3ec1f-4bc6-46ec-9e30-945d70983f9d'::uuid, '3b803ade-85a8-4039-8c6b-18abc4f46fb6'::uuid, false, 8, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('LAB-V2-0009', '3', '3. Cuando se realicen pruebas de inmunología para trasplantes, el profesional de bacteriología cuenta con constancia de asistencia en las acciones de formación continua en la realización de dichas pruebas.', '', '21f3ec1f-4bc6-46ec-9e30-945d70983f9d'::uuid, '3b803ade-85a8-4039-8c6b-18abc4f46fb6'::uuid, false, 9, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('LAB-V2-0010', '4', '4. Cuando se realicen controles de calidad a las “pruebas en el punto de atención del paciente - (Point of Care Testing - POCT)” a otros servicios de salud que hacen uso de estas pruebas, el/la bacteriólogo (a) cuenta con constancia de asistencia en las acciones de formación continua en el manejo de las mismas.', '', '21f3ec1f-4bc6-46ec-9e30-945d70983f9d'::uuid, '3b803ade-85a8-4039-8c6b-18abc4f46fb6'::uuid, false, 10, 'active');
