INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('LAB-V2-0069', '18.8', '18.8. Contrato o convenio escrito con el o los laboratorios que realizan el procesamiento de las muestras, cuando lo requiera. Cuando se trate de sedes de un mismo prestador no requiere convenio o contrato. Si el laboratorio se encuentra en otro país, deberá contar con copia del documento que autorice el funcionamiento en dicho país.', '', '269728eb-96f2-4117-a77a-29e7da9b87ef'::uuid, '3b803ade-85a8-4039-8c6b-18abc4f46fb6'::uuid, false, 69, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('LAB-V2-0070', '18.9', '18.9. Contrato o convenio escrito con el servicio de patología cuando se recepcione fragmentos de tejidos, órganos (biopsias) y material citológico de origen humano para su estudio. Si el servicio de patología se encuentra en otro país, deberá contar con copia del documento que autorice su funcionamiento en dicho país. Cuando se trate de sedes de un mismo prestador no requiere convenio o contrato.', '', '269728eb-96f2-4117-a77a-29e7da9b87ef'::uuid, '3b803ade-85a8-4039-8c6b-18abc4f46fb6'::uuid, false, 70, 'active');
