INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('QRG-V2-0007', '2.1', '2.1 Profesional de la medicina o de la odontología especialista según la oferta del prestador de servicios de salud con permanencia durante los procedimientos quirúrgicos y de conformidad con lo documentado en el estándar de procesos prioritarios.', '', 'b1a76b03-d820-4e5e-b1a7-02eeb702922d'::uuid, 'f3f8b89e-3462-45ae-8820-a5ab01ad7826'::uuid, false, 7, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('QRG-V2-0008', '2.2', '2.2 Profesional de la medicina especialista en anestesiología,  con permanencia durante los procedimientos documentados  por el prestador de servicios de salud en el estándar de procesos prioritarios, quien realizará solo un procedimiento a la vez y estará presente durante todo el acto quirúrgico', '', 'b1a76b03-d820-4e5e-b1a7-02eeb702922d'::uuid, 'f3f8b89e-3462-45ae-8820-a5ab01ad7826'::uuid, false, 8, 'active');
