INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0005', '1.1', '1.1. Tecnólogo en atención prehospitalaria o técnico profesional en atención prehospitalaria o auxiliar en enfermería,  en cualquier caso, cuenta con constancia de asistencia en las acciones de formación continua en soporte vital básico.', '', 'be768081-b8f4-4db6-852d-7e5d381ed3e8'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 5, 'active');
