INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0025', '5', '5. Para embarcaciones menores (cuya capacidad de transporte no excede las 25 toneladas), motorista y otro tripulante (que puede ser ayudante fluvial), con permisos expedidos por la autoridad competente y adicionalmente cuentan con constancia de asistencia en las acciones de formación continua en primeros auxilios o de primer respondiente.', '', 'be768081-b8f4-4db6-852d-7e5d381ed3e8'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 25, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0026', '6', '6. Para embarcaciones mayores (cuya capacidad de transporte excede las 25 toneladas), la tripulación mínima será la que determina el Ministerio de Transporte para las 6 categorías que conforman este grupo de embarcaciones, con licencias y permisos expedidos por la autoridad competente y adicionalmente cuentan con constancia de asistencia en las acciones de formación continua en primeros auxilios o de primer respondiente.', '', 'be768081-b8f4-4db6-852d-7e5d381ed3e8'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 26, 'active');
