INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0086', '16.2', '16.2. Sistema de telecomunicaciones de doble vía, asignado exclusivamente a la ambulancia, que le permita establecer contacto con su central, base o red de coordinación.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 86, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0087', '16.3', '16.3. Sistema de georreferenciación y comunicación que permita el monitoreo y contacto con la entidad territorial en salud a través del CRUE.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 87, 'active');
