INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0089', '17', '17. Cuenta con:', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, true, 89, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0090', '17.1', '17.1. Extintor para fuegos ABC, con capacidad mínima de carga de 2.26 kg. Para cada uno de los compartimentos de la ambulancia (conductor y paciente).', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 90, 'active');
