INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0093', '', 'Condiciones generales de la embarcación', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, true, 93, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0094', '18', '18. Cuenta con:', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, true, 94, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0095', '18.1', '18.1. El diseño y la construcción de la embarcación cumple con la normatividad vigente a la fecha de la construcción, expedidas por las autoridades competentes.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 95, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0096', '18.2', '18.2.Compartimiento para el paciente que tiene como mínimo las siguientes dimensiones: largo útil 2.20 metros, ancho útil 2.20 metros, altura interna útil 2.0 metros. (sobre estas medidas se autorizan variaciones máximas del 15 %).', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 96, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0097', '18.3', '18.3. Soportes y elementos metálicos de los equipos biomédicos no representan riesgo de accidente.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 97, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0098', '18.4', '18.4. Banco para soportar una camilla principal, construida en material resistente y fijado en la cubierta del vehículo.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 98, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0099', '18.5', '18.5. El piso no debe poseer elementos afilados o cortantes y está fabricado en material lavable, que evite la acumulación del mugre y contaminantes, resistente a los agentes desinfectantes habituales, antideslizante, con las uniones del piso con las paredes herméticamente selladas.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 99, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0100', '18.6', '18.6. La embarcación está fabricada en materiales resistentes al medio acuático.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 100, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0101', '18.7', '18.7. La cubierta inferior del compartimiento del paciente está fabricada en material antideslizante, sin elementos afilados o cortantes, de material lavable, con acabados redondeados, superficies pulidas y resistentes a agentes desinfectantes.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 101, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0102', '18.8', '18.8. La disposición de los soportes y elementos metálicos para equipos de asistencia, deben quedar de tal forma que no produzcan daño a los ocupantes del vehículo.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 102, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0103', '18.9', '18.9. Techo-cubierta de material rígido o plegable, liviano, para proteger y cubrir los compartimientos del paciente, piloto y acompañantes.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 103, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('TAS-V2-0104', '18.10', '18.10. El techo-cubierta debe servir en su parte exterior de soporte a los dispositivos de alerta, luces y exploradoras y en su parte interior para la fijación de los rieles para ubicación de líquidos parenterales y equipos biomédicos.', '', 'd5f501b2-f2c5-40e7-b8ce-0276ca130f4b'::uuid, '3a0da41a-9ff5-4ce7-a0b5-d433c2146a4b'::uuid, false, 104, 'active');
