INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('URG-V2-0044', '16.3', '16.3. Circulación al interior del servicio que permite el flujo y desplazamiento expedito del personal y pacientes, facilitando los procesos de atención inmediata, oportunidad en la atención y las relaciones funcionales e interdependencia con los otros servicios.', '', '037344f7-2191-4220-a483-3f4a81be35a2'::uuid, 'f3344eb5-6465-4a60-be67-132848308476'::uuid, false, 44, 'active');
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_section_header, sort_order, status) VALUES ('URG-V2-0045', '17', '17. Cuando la sala de observación o el ambiente de transición del servicio de urgencias se preste en más de un piso o nivel en la misma edificación, el traslado de los pacientes entre los niveles o pisos, se realizará mediante ascensor para movilización de pacientes en camilla, de uso exclusivo, o rampa de uso exclusivo hasta tres (3) niveles o pisos. A partir de tres (3) o más pisos o niveles contados a partir del nivel más bajo construido, se realizará mediante ascensor para movilización de pacientes en camilla, de uso exclusivo. Adicionalmente, cuenta con una sala de reanimación adicional a la ubicada en el piso o nivel de acceso directo desde el exterior de la edificación.', '', '037344f7-2191-4220-a483-3f4a81be35a2'::uuid, 'f3344eb5-6465-4a60-be67-132848308476'::uuid, false, 45, 'active');
